/**
 * What a `#/settings?…` link asks the Settings surface to do.
 *
 * Pure, and separate from the section component, because this is the whole contract between the
 * URL and the embedded Settings SPA — the part worth asserting. The component around it only wires
 * the result into `AdminContext` and mirrors the search term back.
 *
 * Two parameters, for two different kinds of author:
 *
 * - **`q`** is for a person. It mirrors the search box both ways, so a filtered view can be shared,
 *   bookmarked and reloaded.
 * - **`section`** is for a link generated by something other than a person — an admin notice
 *   sending the merchant to the decision it just described. It carries a section **key**, never a
 *   search term, because a term would have to be the section's *translated* label: a link minted on
 *   an English install would match nothing on a French one.
 */

/** A `useSearchParams()` bag: a value may be absent, single, or repeated. */
export type SearchParams = Record<string, string | string[] | undefined>;

export interface SettingsDeepLink {
  /** Applied verbatim, empty included — the URL is the source of truth for the filter. */
  search: string;
  /** An outline key to reveal, or undefined when the link names none. */
  revealSection?: string;
  /** Open with the "needs a decision" filter already applied. */
  decisions: boolean;
}

/**
 * The last value for a key.
 *
 * A repeated parameter (`?q=a&q=b`) is malformed rather than meaningful, so rather than ignore it —
 * which would silently drop a link that half-works — take the last, the way a querystring's later
 * value normally wins.
 */
function one(value: string | string[] | undefined): string | undefined {
  if (Array.isArray(value)) {
    return value.length > 0 ? value[value.length - 1] : undefined;
  }

  return value;
}

export function settingsDeepLink(params: SearchParams): SettingsDeepLink {
  const section = one(params.section);

  return {
    search: one(params.q) ?? '',
    // An empty `?section=` names nothing; treating it as a request would start a reveal that can
    // never match and would clear the merchant's filters for no reason.
    revealSection: undefined !== section && '' !== section ? section : undefined,
    decisions: '1' === one(params.decisions),
  };
}

/**
 * What `?q=` should become when the search box holds `term`.
 *
 * `undefined` removes the parameter: a bare `?q=` in a link someone pastes is noise that says
 * nothing, and it reads as a setting rather than as the absence of one.
 */
export function mirroredSearchParam(term: string): string | undefined {
  return '' === term ? undefined : term;
}
